Scripts.OnLoad:
if C_Item then
	this:SetBackdropBorderColor(0.4, 0.4, 0.4);
this:SetBackdropColor(0.15,	0.15, 0.15);
getglobal(this:GetName().."Title"):SetText(MI2_FRAME_TEXTS[this:GetName()]);
end

Scripts.OnClick:
if C_Item then
	MI2_SlashParse( this:GetName(), false);
end

Scripts.OnLoad:
if C_Item then
	getglobal(this:GetName().."Text"):SetText(MI2_OPTIONS[this:GetName()].text); 
getglobal(this:GetName().."Low"):Hide();
getglobal(this:GetName().."High"):Hide();
this:SetValueStep( 1 );
MI2_OPTIONS[this:GetName()].val = 1
end

Scripts.OnClick:
if C_Item then
	MI2_TabButton_OnClick( this:GetName()	);
end

if C_Item then
	MI2_SlashParse( this:GetName(), false );
						MI2_OptRecordPlayerHp_OnClick();
end

if C_Item then
	MI2_SearchTab_OnClick( this:GetName() );
end

if C_Item then
	MI2_SearchTab_OnClick( this:GetName() );
end

Scripts.OnVerticalScroll:
if C_Item then
	FauxScrollFrame_OnVerticalScroll( 14, MI2_SearchResult_Update );
end
